# Generate ASIAN_TIER_PLANS
ts_lines.append("export const ASIAN_TIER_PLANS: Record<number, DayMealsStructure[]> = {")
for tier_idx in range(5):
    tdata = asian_archetypes[tier_idx]
    ts_lines.append(f"  // Tier {tier_idx}: {tdata['tierName']}")
    ts_lines.append(f"  {tier_idx}: [")
