    l_len = len(tdata["l"])
    d_len = len(tdata["d"])
    s_len = len(tdata["s"])
    for day in range(1, 31):
        # Staggered modulo so each day's combination of 4 meals is unique and non-repeating across the 30 days
        b_idx = (day - 1) % b_len
        l_idx = (day - 1 + (day // b_len)) % l_len
        d_idx = (day - 1 + 2 * (day // l_len)) % d_len
        s_idx = (day - 1 + 3 * (day // d_len)) % s_len

        b_archetype = tdata["b"][b_idx]
        l_archetype = tdata["l"][l_idx]
