# Helper resolution functions
ts_lines.append("""
/**
 * Resolves the 4-meal plan for a specific day and budget tier index.
 */
export function getTierMealsForDay(
  tierIndex: number,
  dayNumber: number,
  cuisine: 'asian' | 'american'
): DayMealsStructure {
  const safeTier = Math.max(0, Math.min(4, tierIndex));
  const safeDay = Math.max(1, Math.min(30, dayNumber));
  const planMatrix = cuisine === 'american' ? AMERICAN_TIER_PLANS : ASIAN_TIER_PLANS;
  const tierDays = planMatrix[safeTier] || planMatrix[0];
  return tierDays[safeDay - 1] || tierDays[0];
}

/**
 * Maps a numeric USD target budget to the corresponding tier index:
 * < $5.00 -> Tier 0 ($4 Saver)
 * < $7.00 -> Tier 1 ($6 Lean)
 * < $9.00 -> Tier 2 ($8 Balanced)
 * < $11.00 -> Tier 3 ($10 Pro)
 * >= $11.00 -> Tier 4 ($12+ Feast)
 */
export function getTierIndexForBudget(targetBudget: number): number {
  if (targetBudget < 5.0) return 0;
  if (targetBudget < 7.0) return 1;
  if (targetBudget < 9.0) return 2;
  if (targetBudget < 11.0) return 3;
  return 4;
}

/**
 * Dynamically resolves and calibrates the daily meal plan matching the exact budget requested.
 * When switching between budget chips ($4, $6, $8, $10, $12+), completely new meals appear.
 * For intermediate stepper budgets, ingredient prices scale precisely to match the exact cents.
 */
export function resolveMealsForBudgetAndDay(
  dayNumber: number,
  targetBudget: number,
  cuisine: 'asian' | 'american'
): DayMealsStructure {
  const tierIndex = getTierIndexForBudget(targetBudget);
  const baseMeals = getTierMealsForDay(tierIndex, dayNumber, cuisine);

  const baseTotal =
    baseMeals.breakfast.costUsd +
    baseMeals.lunch.costUsd +
    baseMeals.dinner.costUsd +
    baseMeals.snack.costUsd;

  // If already matches target budget within 5 cents, return directly
  if (Math.abs(baseTotal - targetBudget) < 0.05) {
    return baseMeals;
  }

  // Proportionally scale costs so sum matches target budget exactly
  const scale = targetBudget / baseTotal;
  const scaleMeal = (m: AsianMeal): AsianMeal => {
    const scaledCost = Number((m.costUsd * scale).toFixed(2));
    const scaledIngredients = (m.ingredients || []).map((ing) => ({
      ...ing,
      costUsd: Number((ing.costUsd * scale).toFixed(2)),
    }));
    return {
      ...m,
      costUsd: scaledCost,
      ingredients: scaledIngredients,
    };
  };

  const b = scaleMeal(baseMeals.breakfast);
  const l = scaleMeal(baseMeals.lunch);
  const d = scaleMeal(baseMeals.dinner);
  const s = scaleMeal(baseMeals.snack);

  // Exact penny adjustment on dinner to guarantee sum === targetBudget
  const currentSum = Number((b.costUsd + l.costUsd + d.costUsd + s.costUsd).toFixed(2));
  const diff = Number((targetBudget - currentSum).toFixed(2));
  if (Math.abs(diff) > 0.001) {
    d.costUsd = Number((d.costUsd + diff).toFixed(2));
  }

  return { breakfast: b, lunch: l, dinner: d, snack: s };
}
""")

